import { Routes } from '@angular/router';

export const routes: Routes = [
  { path: '', pathMatch: 'full', redirectTo: 'dashboard' },
  {
    path: 'dashboard',
    loadComponent: () => import('./dashboard/dashboard').then((m) => m.Dashboard),
  },
  {
    path: 'roster',
    loadComponent: () => import('./heroes/heroes').then((m) => m.Heroes),
  },
  {
    path: 'detail/:id',
    loadComponent: () => import('./hero-detail/hero-detail').then((m) => m.HeroDetail),
  },
  {
    path: 'missions',
    loadComponent: () => import('./missions/missions').then((m) => m.Missions),
  },
  {
    path: 'threats',
    loadComponent: () => import('./threats/threats').then((m) => m.Threats),
  },
  {
    path: 'recruit',
    loadComponent: () => import('./recruit/recruit').then((m) => m.Recruit),
  },
  {
    path: 'settings',
    loadComponent: () => import('./settings/settings').then((m) => m.Settings),
  },
];
---
import { Component, inject } from '@angular/core';
import { RouterLink, RouterOutlet } from '@angular/router';
import { NgIcon, provideIcons } from '@ng-icons/core';
import {
  lucideBell,
  lucideChevronRight,
  lucideLayoutDashboard,
  lucideMoon,
  lucideRadar,
  lucideSettings,
  lucideShieldAlert,
  lucideSun,
  lucideTarget,
  lucideUserPlus,
  lucideUsers,
} from '@ng-icons/lucide';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HlmIconImports } from '@spartan-ng/helm/icon';
import { HlmInputImports } from '@spartan-ng/helm/input';
import { HlmSidebarImports } from '@spartan-ng/helm/sidebar';
import { HlmTooltipImports } from '@spartan-ng/helm/tooltip';
import { HlmTypographyImports } from '@spartan-ng/helm/typography';
import { AppViewModel } from './app.view-model';

@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    NgIcon,
    HlmAvatarImports,
    HlmButtonImports,
    HlmIconImports,
    HlmInputImports,
    HlmSidebarImports,
    HlmTooltipImports,
    HlmTypographyImports,
  ],
  providers: [
    AppViewModel,
    provideIcons({
      lucideBell,
      lucideChevronRight,
      lucideLayoutDashboard,
      lucideMoon,
      lucideRadar,
      lucideSettings,
      lucideShieldAlert,
      lucideSun,
      lucideTarget,
      lucideUserPlus,
      lucideUsers,
    }),
  ],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App {
  protected readonly vm = inject(AppViewModel);
}
---
<div hlmSidebarWrapper class="app">
  <hlm-sidebar>
    <div hlmSidebarHeader class="app__brand">
      <ng-icon hlmIcon name="lucideRadar" />
      <span hlmLarge>Hero Ops Console</span>
    </div>

    <div hlmSidebarContent>
      <div hlmSidebarGroup>
        <div hlmSidebarGroupLabel>Operations</div>
        <nav aria-label="Primary">
          <ul hlmSidebarMenu>
            @for (item of vm.nav(); track item.path) {
              <li hlmSidebarMenuItem>
                <a
                  hlmSidebarMenuButton
                  [routerLink]="item.path"
                  [isActive]="item.active"
                  [attr.aria-current]="item.active ? 'page' : null"
                >
                  <ng-icon hlmIcon [name]="item.icon" />
                  <span>{{ item.label }}</span>
                </a>
              </li>
            }
          </ul>
        </nav>
      </div>
    </div>

    <div hlmSidebarFooter class="app__account">
      <hlm-avatar size="sm">
        <span hlmAvatarFallback>OP</span>
      </hlm-avatar>
      <span hlmSmall>Operator</span>
    </div>
  </hlm-sidebar>

  <main hlmSidebarInset class="app__main">
    <header class="app__topbar">
      <div class="app__start">
        <button hlmSidebarTrigger></button>
        <nav aria-label="Breadcrumb">
          <ol class="app__crumbs">
            @for (crumb of vm.crumbs(); track $index; let last = $last) {
              <li class="app__crumb" [attr.aria-current]="last ? 'page' : null">
                <span hlmSmall>{{ crumb }}</span>
                @if (!last) {
                  <ng-icon hlmIcon name="lucideChevronRight" />
                }
              </li>
            }
          </ol>
        </nav>
      </div>

      <div class="app__search">
        <input hlmInput type="search" aria-label="Search heroes" placeholder="Search heroes" />
      </div>

      <div class="app__actions">
        <button
          hlmBtn
          type="button"
          variant="ghost"
          size="icon"
          hlmTooltip="Notifications"
          aria-label="Notifications"
        >
          <ng-icon hlmIcon name="lucideBell" />
        </button>
        <button
          hlmBtn
          type="button"
          variant="ghost"
          size="icon"
          [hlmTooltip]="vm.themeLabel()"
          [attr.aria-label]="vm.themeLabel()"
          (click)="vm.toggleTheme()"
        >
          <ng-icon hlmIcon [name]="vm.dark() ? 'lucideSun' : 'lucideMoon'" />
        </button>
        <hlm-avatar size="sm">
          <span hlmAvatarFallback>OP</span>
        </hlm-avatar>
      </div>
    </header>

    <div class="app__content">
      <router-outlet />
    </div>
  </main>
</div>
